def four_sum_count(nums1, nums2, nums3, nums4):
    sum_counts = {}
    for a in nums1:
        for b in nums2:
            s = a + b
            sum_counts[s] = sum_counts.get(s, 0) + 1                # tally every possible sum of the first two arrays
    count = 0
    for c in nums3:
        for d in nums4:
            target = -(c + d)
            count += sum_counts.get(target, 0)                        # look up how many pairs complete a sum of zero
    return count


