#include <bits/stdc++.h>
using namespace std;

int fourSumCount(vector<int>& nums1, vector<int>& nums2, vector<int>& nums3, vector<int>& nums4) {
    unordered_map<int, int> sumCounts;
    for (int a : nums1) {
        for (int b : nums2) {
            sumCounts[a + b]++;                                             // tally every possible sum of the first two
        }
    }
    int count = 0;
    for (int c : nums3) {
        for (int d : nums4) {
            auto it = sumCounts.find(-(c + d));
            if (it != sumCounts.end()) count += it->second;                    // look up how many pairs complete a sum of zero
        }
    }
    return count;
}

int main() {
    vector<int> nums1 = {1, 2}, nums2 = {-2, -1}, nums3 = {-1, 2}, nums4 = {0, 2};
    cout << fourSumCount(nums1, nums2, nums3, nums4) << endl;
    return 0;
}
